from collections import deque
class Solution:
    def timeTaken(self, arrival, state):
        n = len(arrival)
        q = [deque(), deque()]
        ans = [0] * n
        i = t = done = 0
        last = -1
        while done < n:
            while i < n and arrival[i] <= t:
                q[state[i]].append(i)
                i += 1
            picked = None
            if q[1] and last != 0:
                picked = (q[1].popleft(), 1)
            elif q[0]:
                picked = (q[0].popleft(), 0)
            elif q[1]:
                picked = (q[1].popleft(), 1)
            if picked:
                idx, st = picked
                ans[idx] = t
                last = st
                done += 1
            else:
                last = -1
            t += 1
        return ans

