class Solution {
public:
    vector<int> timeTaken(vector<int>& arrival, vector<int>& state) {
        int n = arrival.size();
        queue<int> q[2];
        vector<int> ans(n);
        long long t = 0;
        int i = 0, done = 0, last = -1;
        while (done < n) {
            while (i < n && arrival[i] <= t) q[state[i]].push(i++);
            int pick = -1, st = -1;
            if (!q[1].empty() && last != 0) { st = 1; }
            else if (!q[0].empty()) { st = 0; }
            else if (!q[1].empty()) { st = 1; }
            if (st != -1) { pick = q[st].front(); q[st].pop(); ans[pick] = t; last = st; done++; }
            else last = -1;
            t++;
        }
        return ans;
    }
};

