import java.util.*;
class Solution {
    public int[] timeTaken(int[] arrival, int[] state) {
        int n = arrival.length;
        Queue<Integer>[] q = new ArrayDeque[2];
        q[0] = new ArrayDeque<>(); q[1] = new ArrayDeque<>();
        int[] ans = new int[n];
        long t = 0; int i = 0, done = 0, last = -1;
        while (done < n) {
            while (i < n && arrival[i] <= t) q[state[i++]].add(i - 1);
            int st = -1;
            if (!q[1].isEmpty() && last != 0) st = 1;
            else if (!q[0].isEmpty()) st = 0;
            else if (!q[1].isEmpty()) st = 1;
            if (st != -1) { int p = q[st].poll(); ans[p] = (int) t; last = st; done++; }
            else last = -1;
            t++;
        }
        return ans;
    }
}

