    const n = arrival.length;
    const q = [[], []];
    const ans = new Array(n);
    let t = 0, i = 0, done = 0, last = -1;
    while (done < n) {
        while (i < n && arrival[i] <= t) q[state[i++]].push(i - 1);
        let st = -1;
        if (q[1].length && last !== 0) st = 1;
        else if (q[0].length) st = 0;
        else if (q[1].length) st = 1;
        if (st !== -1) { const p = q[st].shift(); ans[p] = t; last = st; done++; }
        else last = -1;
        t++;
    }
    return ans;
};
